name: Label PR

on:
  pull_request:
    types:
      - opened
    branches:
      - main

jobs:
  add-pr-labels:
    name: Add PR labels
    runs-on: ubuntu-latest
    permissions:
      pull-requests: write
    steps:
      - uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd # v8.0.0
        env:
          PULL_REQUEST_TITLE: ${{ github.event.pull_request.title }}
        with:
          script: |
            const labelsToAdd = []

            const pullRequest = {
              number: ${{ github.event.pull_request.number }},
              title: process.env.PULL_REQUEST_TITLE,
              labelsNames: ${{ toJson(github.event.pull_request.labels.*.name) }}
            }

            // Select label based on the type in PR title
            const pullRequestTypeToLabelName = {
              breaking: 'breaking',
              feat: 'feature',
              fix: 'bug',
              build: 'build',
              ci: 'ci',
              docs: 'documentation',
              enhancement: 'enhancement',
              chore: 'dependencies',
              perf: 'performance',
              style: 'style',
              test: 'test',
              refactor: 'refactor',
              revert: 'revert'
            }

            for (const [pullRequestType, labelName] of Object.entries(
              pullRequestTypeToLabelName
            )) {
              if (
                pullRequest.title.startsWith(pullRequestType) &&
                !pullRequest.labelsNames.includes(
                  pullRequestTypeToLabelName[pullRequestType]
                )
              ) {
                labelsToAdd.push(labelName)

                break
              }
            }

            // Add selected labels
            if (labelsToAdd.length > 0) {
              github.rest.issues.addLabels({
                issue_number: pullRequest.number,
                owner: context.repo.owner,
                repo: context.repo.repo,
                labels: labelsToAdd
              })
            }

import { defineHandler } from 'nitro'

export default defineHandler(() => ({
  name: 'nitro-imessage-agent',
  status: 'ready',
}))

import { generateText, stepCountIs } from 'ai'
import { createRequestLogger, initLogger } from 'evlog'
import { createAILogger, createEvlogIntegration } from 'evlog/ai'
import { tools } from '../tools/index.ts'
import { useBot } from './bot.ts'

const SERVICE_NAME = 'nitro-imessage-agent'
const MODEL = 'google/gemini-3-flash'
const SYSTEM_PROMPT = `You are a friendly assistant texting back over iMessage. Keep replies short, casual, and plain text. No markdown.

When recommending Nuxt modules, prefer official modules (type "official", maintained by the Nuxt core team) over community ones unless the user explicitly asks for alternatives or no official option exists.`

// Approximate AI Gateway pricing per 1M tokens (in USD). Adjust as needed.
const COST_MAP = {
  'gemini-3-flash': { input: 0.1, output: 0.4 },
  'claude-sonnet-4.5': { input: 3, output: 15 },
  'gpt-4o-mini': { input: 0.15, output: 0.6 },
}

let _loggerInitialized = false
function ensureLoggerInit(): void {
  if (_loggerInitialized) return
  initLogger({ env: { service: SERVICE_NAME } })
  _loggerInitialized = true
}

export async function generateReply(prompt: string): Promise<string> {
  'use step'

  ensureLoggerInit()

  const log = createRequestLogger({})
  log.set({ step: 'generateReply', model: MODEL, prompt })

  const ai = createAILogger(log, {
    cost: COST_MAP,
    toolInputs: { maxLength: 500 },
  })

  try {
    const { text } = await generateText({
      model: ai.wrap(MODEL),
      system: SYSTEM_PROMPT,
      prompt,
      tools,
      stopWhen: stepCountIs(10),
      experimental_telemetry: {
        isEnabled: true,
        integrations: [createEvlogIntegration(ai)],
      },
    })
    log.set({ reply: text })
    return text
  } finally {
    log.emit()
  }
}

export async function postReply(threadId: string, text: string): Promise<void> {
  'use step'

  if (!text.trim()) return

  const { sendblue } = useBot()
  await sendblue.postMessage(threadId, text)
}

import { defineHandler } from 'nitro'
import { useBot } from '../../utils/bot.ts'

export default defineHandler(async (event) => {
  const { chat } = useBot()
  await chat.initialize()
  return await chat.webhooks.sendblue(event.req, {
    waitUntil: task => event.waitUntil(task),
  })
})

