  "compilerOptions": {
    "paths": {
      "~/*": ["./*"]
    },
    "plugins": [{ "name": "workflow" }]
  },
}

import type { Config } from 'automd'

const config: Config = {
  input: ['README.md', '**/*.md']
}

export default config

import { generateReply, postReply } from '../server/utils/agent-steps.ts'

export async function replyToMessage(threadId: string, prompt: string): Promise<void> {
  'use workflow'

  const text = await generateReply(prompt)
  if (text) await postReply(threadId, text)
}

import { definePlugin } from 'nitro'
import { start } from 'workflow/api'
import { useBot } from '../utils/bot.ts'
import { replyToMessage } from '../../workflows/reply.ts'

export default definePlugin(() => {
  const { chat } = useBot()

  chat.onNewMention(async (thread, message) => {
    await thread.subscribe()
    if (message.text?.trim()) {
      await thread.startTyping()
      await start(replyToMessage, [thread.id, message.text])
    }
  })

  chat.onSubscribedMessage(async (thread, message) => {
    if (message.text?.trim()) {
      await thread.startTyping()
      await start(replyToMessage, [thread.id, message.text])
    }
  })
})

import { Chat, type StateAdapter } from 'chat'
import { createSendblueAdapter, type SendblueAdapter } from 'chat-adapter-sendblue'
import { createMemoryState } from '@chat-adapter/state-memory'
import { createRedisState } from '@chat-adapter/state-redis'

interface Bot {
  chat: Chat
  sendblue: SendblueAdapter
}

let _bot: Bot | undefined

function resolveStateAdapter(): StateAdapter {
  const url = process.env.REDIS_URL ?? process.env.KV_URL
  if (url) return createRedisState({ url })
  return createMemoryState()
}

export function useBot(): Bot {
  if (_bot) return _bot

  const sendblue = createSendblueAdapter()

  const chat = new Chat({
    userName: 'imessage-agent',
    adapters: { sendblue },
    state: resolveStateAdapter(),
  })

  _bot = { chat, sendblue }
  return _bot
}
